out['00775'].update(indication='Neoadjuvant adult high-risk HER2-positive locally advanced, inflammatory or early breast cancer.',sequence='Six 21-day cycles → surgery/pathology → separately selected adjuvant HER2 therapy (e.g. trastuzumab or T-DM1 as appropriate) to complete one year. No planned Day 15 paclitaxel.',schedule='Pertuzumab/trastuzumab IV and carboplatin AUC6 on Day1; paclitaxel 80 mg/m² on Days1 and8. Paclitaxel reductions 80→70→60 mg/m²; carboplatin AUC6→5→4.',eligibility='Age≥18, HER2 positive, ECOG0–1, adequate organ function, LVEF≥55% or ≥50% after completed anthracyclines. Baseline ANC<1.5 is excluded; severe hepatic impairment excludes paclitaxel.',support={'page':7,'risk':'Day1 high (carboplatin AUC6); Day8 low (paclitaxel alone). Antibodies minimal. Postoperative risk follows selected medicine; do not label unknown T-DM1/other ADC as minimal.','premedication_page':8,'premedication':'First paclitaxel: dexamethasone8mg IV, chlorphenamine10mg IV, famotidine20mg IV 30min before. Day8 onward no routine dexamethasone unless consultant adds for reaction/risk; chlorphenamine continues and famotidine may be omitted only with consultant guidance when no reaction. Reconcile overlapping antiemetic steroids.','gcsf':'May be required; local policy. Not universally mandatory.'},administration={'pages':[1,2],'detail':'Both antibodies before chemotherapy. Pertuzumab first60min+60min observation, subsequent30min+30–60min observation (not required after3 tolerated treatments). Trastuzumab first90min, later30min; observation6h from first start,2h from subsequent starts. Paclitaxel60min D1/D8 via non-PVC and0.22micron filter; carboplatin30min D1. Local observation deviations documented.'},pages={'schedule':1,'eligibility':3,'monitoring':4,'missed_dose_counts':5,'organ_function':6,'adverse_events_emesis':7,'premedication':8})
